#!/usr/bin/env node
// Flattens src/ into dist/project_rain_bundle.lua
const fs = require("fs");
const path = require("path");

const ROOT = path.resolve(__dirname, "..");
const SRC = path.join(ROOT, "src");
const DIST = path.join(ROOT, "dist");

function walk(dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, out);
    else if (e.name.endsWith(".lua")) out.push(p);
  }
  return out;
}

const parts = [
  "-- GENERATED by tools/bundle.js",
  "local __modules, __cache = {}, {};",
  `local function __require(path)
    if __cache[path] ~= nil then return __cache[path] end
    local m = __modules[path]
    if not m then error("[bundle] missing module: " .. tostring(path)) end
    local res = m()
    __cache[path] = res
    return res
end
require = __require
getgenv().require = __require
builder_require = builder_require or __require
getgenv().script_require = builder_require`,
];

for (const f of walk(SRC)) {
  const rel = path.relative(SRC, f).replace(/\.lua$/, "").replace(/\\/g, "/");
  parts.push(`__modules[${JSON.stringify("@src/" + rel)}] = function()\n${fs.readFileSync(f, "utf8")}\nend;`);
}
parts.push(`__require("@src/init");`);

fs.mkdirSync(DIST, { recursive: true });
fs.writeFileSync(path.join(DIST, "project_rain_bundle.lua"), parts.join("\n"));
console.log("Wrote dist/project_rain_bundle.lua");